package dev.irisvisualizer.editor;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Properties;
import java.util.function.Function;

/** Placement scheduling/source authoring; no assembly, native placement or cave search is executed. */
public final class StructurePlacements {
    public static final List<String> CONTEXTS = List.of("dimensions", "biomes", "regions");
    public static final List<String> LIST_FIELDS = List.of("structures");
    public static final List<String> EDITABLE = List.of("structures", "nativeStructures", "placementId", "nativeSuppression", "distribution", "spacing", "separation", "salt", "density", "ringCount", "ringDistance", "ringSpread", "minHeight", "maxHeight", "underground", "anchor", "caveBiomes", "caveAnchorAttempts", "caveAnchorScanStep", "caveMinimumClearance", "underwater");
    public static final List<String> NATIVE_FIELDS = List.of("structure", "weight");
    public static final List<String> SCALARS = List.of("salt", "density", "caveAnchorAttempts", "caveAnchorScanStep", "caveMinimumClearance");
    public static final List<String> BOOLEANS = List.of("underground", "underwater");
    public static final List<String> ENUMS = List.of("distribution", "anchor", "nativeSuppression");
    public static final int MAXIMUM_ENTRIES=64;
    private static final Properties DATA=new Properties();
    static { try (var input=StructurePlacements.class.getResourceAsStream("/structure-placement-fields.properties")) { if (input==null) throw new IOException("Missing pinned structure placement definitions");DATA.load(input);if (!"exactlyOneBackend".equals(DATA.getProperty("backend.policy")) || !"LEGACY".equals(DATA.getProperty("anchor.default"))) throw new IOException("Unsupported placement policy"); } catch (IOException failure) { throw new ExceptionInInitializerError(failure); } }
    private static void authorize(String path) { String base=ResourceTypes.base(path);if (base==null || !CONTEXTS.contains(base)) throw new IllegalArgumentException("Structure placements require a dimension, biome or region resource"); }
    private static void limit(int size,boolean adding) { if (size>MAXIMUM_ENTRIES || adding && size>=MAXIMUM_ENTRIES) throw new IllegalArgumentException("Structure placement lists have a 64-entry editor limit"); }
    public static String prefix() { return "structurePlacement#"; }
    public static String prefix(int index) { if (index<0) throw new IllegalArgumentException("Select a placement");return prefix()+index+"."; }
    public static String help(String field) { return DATA.getProperty(field+".description",""); }
    public static String defaultToken(String field) { String value=DATA.getProperty(field+".default");if (value==null) throw new IllegalArgumentException("Unsupported placement field");return value; }
    public static List<String> choices(String field) { if (field==null || !ENUMS.contains(field)) throw new IllegalArgumentException("Unsupported placement enum");return List.of(DATA.getProperty(field+".choices").split(",")); }
    public static String choiceHelp(String field,String choice) { return DATA.getProperty(field+"."+choice+".description",""); }
    public static String constraints(String field) { return ("int".equals(DATA.getProperty(field+".type")) ? "Exact integer " : "Finite number ")+DATA.getProperty(field+".minimum")+".."+DATA.getProperty(field+".maximum")+"."; }
    static List<LosslessJson> entries(LosslessJson root) { return root.token("structures")==null ? null : root.objectArray("structures"); }
    static byte[] edit(byte[] original,int index,Function<LosslessJson,byte[]> operation) { var root=new LosslessJson(original);var entries=entries(root);if (entries==null) throw new IllegalArgumentException("Create a placement first");limit(entries.size(),false);return root.objectArrayEdit("structures",index,operation); }
    public static List<String> references(PackWorkspace workspace,String field) {
        if (field==null) throw new IllegalArgumentException("Choose a reference field");if (field.equals("caveBiomes")) return ResourceTypes.referenceKeys(workspace,"biomes");if (!field.equals("structures")) throw new IllegalArgumentException("Unsupported placement reference list");
        String prefix="structures/";return workspace.paths().stream().filter(p -> p.startsWith(prefix) && p.endsWith(".json")).map(p -> p.substring(prefix.length(),p.length()-5)).filter(ResourceTypes::referenceKey).sorted().toList();
    }
    static List<String> strings(LosslessJson entry,String field) { if (field==null || !List.of("structures","caveBiomes").contains(field)) throw new IllegalArgumentException("Unsupported placement string list");String token=entry.token(field);return token==null || token.equals("null") ? null : entry.stringArrayPath(field); }
    static List<LosslessJson> natives(LosslessJson entry) { String token=entry.token("nativeStructures");return token==null || token.equals("null") ? null : entry.objectArray("nativeStructures"); }
    static String backend(LosslessJson entry) { var iris=strings(entry,"structures");var nativeSources=natives(entry);boolean a=iris!=null && !iris.isEmpty(),b=nativeSources!=null && !nativeSources.isEmpty();if (a==b) throw new IllegalArgumentException("Placement must declare exactly one non-empty backend");return a ? "IRIS" : "NATIVE"; }
    private static void id(String input) { if (input==null || !input.equals(input.trim()) || !input.isEmpty() && input.isBlank() || input.indexOf(0)>=0) throw new IllegalArgumentException("Use an ID without surrounding whitespace/NUL, or empty for derived identity"); }
    private static void uniqueId(List<LosslessJson> entries,String input,int excluded) { if (input.isEmpty() || entries==null) return;for (int i=0;i<entries.size();i++) if (i!=excluded) { String old;try { old=entries.get(i).stringToken("placementId"); } catch (IllegalArgumentException unsupported) { continue; }if (old!=null && old.trim().equals(input)) throw new IllegalArgumentException("Placement ID already exists in this resource"); } }
    private static void registry(String input) { if (input==null || !input.matches("[a-z0-9_.-]+:[a-z0-9/._-]+")) throw new IllegalArgumentException("Enter a lowercase namespace:key; live registration is unverified"); }
    public static byte[] change(String path,byte[] original,RiverProfiles.Action action,int index,String newId,String selectedBackend,String source,PackWorkspace workspace) {
        authorize(path);if (action==null) throw new IllegalArgumentException("Choose a placement action");var root=new LosslessJson(original);var list=entries(root);int size=list==null ? 0 : list.size();limit(size,action==RiverProfiles.Action.ADD || action==RiverProfiles.Action.DUPLICATE);
        if (action!=RiverProfiles.Action.ADD && (index<0 || index>=size)) throw new IllegalArgumentException("Select an existing placement");
        if (action==RiverProfiles.Action.ADD || action==RiverProfiles.Action.DUPLICATE) { id(newId);if (newId.isEmpty()) throw new IllegalArgumentException("New/copy placements require an explicit ID; pack-wide uniqueness is unverified");uniqueId(list,newId,-1); }
        if (action==RiverProfiles.Action.ADD) {
            var seed=new LosslessJson("{}".getBytes(StandardCharsets.UTF_8));byte[] next=seed.enableStringPath("placementId",newId);
            if ("IRIS".equals(selectedBackend)) { if (!references(workspace,"structures").contains(source)) throw new IllegalArgumentException("Choose an exact in-pack Iris structure file");next=new LosslessJson(new LosslessJson(next).enableArray("structures")).stringArrayPath("structures",0,source); }
            else if ("NATIVE".equals(selectedBackend)) { registry(source);byte[] nativeSource=seed.enableStringPath("structure",source);next=new LosslessJson(new LosslessJson(next).enableArray("nativeStructures")).objectArrayInsert("nativeStructures",0,nativeSource); }
            else throw new IllegalArgumentException("Choose the Iris or native backend");
            return new LosslessJson(list==null ? root.enableArray("structures") : original).objectArrayInsert("structures",size,next);
        }
        if (action==RiverProfiles.Action.DUPLICATE) { var entry=list.get(index);String old=entry.stringToken("placementId");byte[] next=old==null ? entry.enableStringPath("placementId",newId) : entry.stringValue("placementId",newId);return root.objectArrayInsert("structures",index+1,next); }
        if (action==RiverProfiles.Action.REMOVE && size==1) return root.removeField("structures");return BiomeLayers.changeLayers(root,"structures",action,index);
    }
    static String text(LosslessJson entry,String field) { String value=entry.stringToken(field);return value==null ? defaultToken(field) : value; }
    public static byte[] setId(String path,byte[] original,int index,String input) { authorize(path);id(input);var list=entries(new LosslessJson(original));uniqueId(list,input,index);return edit(original,index,e -> putString(e,"placementId",input)); }
    private static byte[] putString(LosslessJson entry,String field,String input) { String old=entry.stringToken(field);return input.equals(old) ? entry.sourceBytes() : old==null ? entry.enableStringPath(field,input) : entry.stringValue(field,input); }
    static String number(LosslessJson entry,String field) { String token=entry.token(field);if (token==null) return defaultToken(field);try { if (!LosslessJson.numericToken(token)) throw new NumberFormatException();var value=new BigDecimal(token);if ("int".equals(DATA.getProperty(field+".type"))) value.intValueExact();else if (!Double.isFinite(value.doubleValue())) throw new NumberFormatException();return token; } catch (NumberFormatException | ArithmeticException invalid) { throw new IllegalArgumentException("Stored placement number has an unsupported type, width or finite value",invalid); } }
    private static BigDecimal input(String field,String input) { try { var value=new BigDecimal(input);if ("int".equals(DATA.getProperty(field+".type"))) value.intValueExact();if (!Double.isFinite(value.doubleValue()) || value.compareTo(new BigDecimal(DATA.getProperty(field+".minimum")))<0 || value.compareTo(new BigDecimal(DATA.getProperty(field+".maximum")))>0) throw new NumberFormatException();return value; } catch (NumberFormatException | ArithmeticException | NullPointerException invalid) { throw new IllegalArgumentException(constraints(field),invalid); } }
    private static byte[] putNumber(LosslessJson entry,String field,BigDecimal value) { number(entry,field);if (entry.token(field)==null) return entry.enable(field,value.toString());return new BigDecimal(entry.token(field)).compareTo(value)==0 ? entry.sourceBytes() : "int".equals(DATA.getProperty(field+".type")) ? entry.integer(field,value.intValueExact()) : entry.number(field,value.doubleValue()); }
    public static byte[] setScalar(String path,byte[] original,int index,String field,String input) { authorize(path);if (field==null || !SCALARS.contains(field)) throw new IllegalArgumentException("Select a supported placement scalar");var value=input(field,input);return edit(original,index,e -> putNumber(e,field,value)); }
    public static byte[] setGrid(String path,byte[] original,int index,String spacing,String separation) { authorize(path);var a=input("spacing",spacing);var b=input("separation",separation);if (b.compareTo(a)>=0) throw new IllegalArgumentException("Separation must be smaller than spacing");return edit(original,index,e -> { number(e,"spacing");number(e,"separation");return putNumber(new LosslessJson(putNumber(e,"spacing",a)),"separation",b); }); }
    public static byte[] setHeights(String path,byte[] original,int index,String min,String max) { authorize(path);var a=input("minHeight",min);var b=input("maxHeight",max);if (a.compareTo(b)>0) throw new IllegalArgumentException("Minimum world Y must not exceed maximum");return edit(original,index,e -> { number(e,"minHeight");number(e,"maxHeight");return putNumber(new LosslessJson(putNumber(e,"minHeight",a)),"maxHeight",b); }); }
    public static byte[] setRings(String path,byte[] original,int index,String count,String distance,String spread) { authorize(path);var a=input("ringCount",count);var b=input("ringDistance",distance);var c=input("ringSpread",spread);long radius=((a.longValueExact()+c.longValueExact()-1)/c.longValueExact())*b.longValueExact();if (radius>Integer.MAX_VALUE) throw new IllegalArgumentException("Concentric ring radius exceeds signed 32-bit chunk coordinates");return edit(original,index,e -> { for (String f : List.of("ringCount","ringDistance","ringSpread")) number(e,f);return putNumber(new LosslessJson(putNumber(new LosslessJson(putNumber(e,"ringCount",a)),"ringDistance",b)),"ringSpread",c); }); }
    static boolean bool(LosslessJson entry,String field) { if (field==null || !BOOLEANS.contains(field)) throw new IllegalArgumentException("Unsupported placement toggle");String token=entry.token(field);if (token==null) token=defaultToken(field);if (!token.equals("true") && !token.equals("false")) throw new IllegalArgumentException("Stored placement toggle is not boolean");return token.equals("true"); }
    public static byte[] setBoolean(String path,byte[] original,int index,String field,boolean input) { authorize(path);return edit(original,index,e -> { bool(e,field);return e.token(field)==null ? e.enable(field,Boolean.toString(input)) : e.bool(field,input); }); }
    public static byte[] setChoice(String path,byte[] original,int index,String field,String choice) { authorize(path);if (choice==null || !choices(field).contains(choice)) throw new IllegalArgumentException("Choose a pinned placement option");if (field.equals("nativeSuppression") && choice.equals("REPLACE_SOURCE") && !DimensionFields.dimension(path)) throw new IllegalArgumentException("Native replacement suppression is dimension-only");return edit(original,index,e -> { if (field.equals("anchor") && backend(e).equals("NATIVE") && !choice.equals("LEGACY")) throw new IllegalArgumentException("Native sources require the LEGACY/omitted anchor");return putString(e,field,choice); }); }
    private static void unique(List<String> entries,String input,int excluded) { for (int i=0;i<entries.size();i++) if (i!=excluded && entries.get(i).trim().toLowerCase(Locale.ROOT).equals(input.trim().toLowerCase(Locale.ROOT))) throw new IllegalArgumentException("Duplicate source/reference key"); }
    public static byte[] setReference(String path,byte[] original,int index,String field,int row,String key,PackWorkspace workspace) { authorize(path);if (!references(workspace,field).contains(key)) throw new IllegalArgumentException("Choose an exact in-pack file key");return edit(original,index,e -> { var list=strings(e,field);if (list==null) throw new IllegalArgumentException("Add references first");limit(list.size(),false);if (row<0 || row>=list.size()) throw new IllegalArgumentException("Select a reference");unique(list,key,row);return list.get(row).equals(key) ? e.sourceBytes() : e.stringArrayPath(field,row,key); }); }
    public static byte[] changeReference(String path,byte[] original,int index,String field,RiverProfiles.Action action,int row,String key,PackWorkspace workspace) { authorize(path);if (action==null || action==RiverProfiles.Action.DUPLICATE) throw new IllegalArgumentException("Choose add/remove/move; duplicate references are unsupported");if (action==RiverProfiles.Action.ADD && !references(workspace,field).contains(key)) throw new IllegalArgumentException("Choose an exact in-pack key");return edit(original,index,e -> { var list=strings(e,field);int size=list==null ? 0 : list.size();limit(size,action==RiverProfiles.Action.ADD);if (field.equals("structures") && !backend(e).equals("IRIS")) throw new IllegalArgumentException("Iris references require the Iris backend");if (action==RiverProfiles.Action.ADD) { if (list!=null) unique(list,key,-1);return new LosslessJson(list==null ? e.enableArray(field) : e.sourceBytes()).stringArrayPath(field,size,key); }if (row<0 || row>=size) throw new IllegalArgumentException("Select a reference");return switch(action) { case REMOVE -> { if (size==1 && field.equals("structures")) throw new IllegalArgumentException("Keep one Iris source");yield size==1 ? e.removeField(field) : e.stringArrayPath(field,row,null); }case UP -> { if (row==0) throw new IllegalArgumentException("Already first");yield e.stringArrayMove(field,row,row-1); }case DOWN -> { if (row+1==size) throw new IllegalArgumentException("Already last");yield e.stringArrayMove(field,row,row+1); }default -> throw new IllegalArgumentException("Unsupported reference action"); }; }); }
    static String nativeKey(LosslessJson source) { String value=source.stringToken("structure");return value==null ? "" : value; }
    static String nativeWeight(LosslessJson source) { String token=source.token("weight");if (token==null) return "1";try { if (!LosslessJson.numericToken(token)) throw new NumberFormatException();new BigDecimal(token).intValueExact();return token; } catch (NumberFormatException | ArithmeticException invalid) { throw new IllegalArgumentException("Stored native weight is not an exact signed 32-bit integer",invalid); } }
    static void sourceList(LosslessJson entry) { if (!backend(entry).equals("NATIVE")) throw new IllegalArgumentException("Native sources require the native backend");limit(natives(entry).size(),false); }
    private static void sourceTotal(LosslessJson entry) { long total=0;for (var source : natives(entry)) { int w=new BigDecimal(nativeWeight(source)).intValueExact();if (w<1) throw new IllegalArgumentException("Native weights must be positive");total+=w; }if (total>Integer.MAX_VALUE) throw new IllegalArgumentException("Native weight total exceeds signed 32-bit range"); }
    public static byte[] setNativeKey(String path,byte[] original,int index,int row,String key) { authorize(path);registry(key);return edit(original,index,e -> { sourceList(e);var keys=natives(e).stream().map(StructurePlacements::nativeKey).toList();unique(keys,key,row);return e.objectArrayEdit("nativeStructures",row,s -> putString(s,"structure",key)); }); }
    public static byte[] setNativeWeight(String path,byte[] original,int index,int row,String text) { authorize(path);var weight=input("native.weight",text);return edit(original,index,e -> { sourceList(e);var next=new LosslessJson(e.objectArrayEdit("nativeStructures",row,s -> { nativeWeight(s);return s.token("weight")==null ? s.enable("weight",weight.toString()) : new BigDecimal(s.token("weight")).compareTo(weight)==0 ? s.sourceBytes() : s.integer("weight",weight.intValueExact()); }));sourceTotal(next);return next.sourceBytes(); }); }
    public static byte[] changeNative(String path,byte[] original,int index,RiverProfiles.Action action,int row,String key) { authorize(path);if (action==null || action==RiverProfiles.Action.DUPLICATE) throw new IllegalArgumentException("Choose add/remove/move; duplicate native keys are unsupported");if (action==RiverProfiles.Action.ADD) registry(key);return edit(original,index,e -> { sourceList(e);var list=natives(e);limit(list.size(),action==RiverProfiles.Action.ADD);if (action==RiverProfiles.Action.ADD) { unique(list.stream().map(StructurePlacements::nativeKey).toList(),key,-1);var next=new LosslessJson(e.objectArrayInsert("nativeStructures",list.size(),new LosslessJson("{}".getBytes(StandardCharsets.UTF_8)).enableStringPath("structure",key)));sourceTotal(next);return next.sourceBytes(); }if (row<0 || row>=list.size()) throw new IllegalArgumentException("Select a native source");if (action==RiverProfiles.Action.REMOVE && list.size()==1) throw new IllegalArgumentException("Keep one native source");return BiomeLayers.changeLayers(e,"nativeStructures",action,row); }); }
    static List<String> readOnlyPaths(LosslessJson root) { return readOnlyPaths(root,"dimensions"); }
    static List<String> readOnlyPaths(LosslessJson root,String base) { var paths=new ArrayList<String>();try { var list=entries(root);if (list==null) return List.of();limit(list.size(),false);for (int i=0;i<list.size();i++) { var entry=list.get(i);for (String field : entry.fields()) { String at="structures["+i+"]."+field;try { if (StructurePlacementIntegration.OBJECT_FIELDS.contains(field)) { for (String detail : StructurePlacementIntegration.readOnlyPaths(entry,i,base,field)) paths.add("structures["+i+"]."+detail); }else if (!EDITABLE.contains(field)) paths.add(at);else if (field.equals("nativeStructures")) { var sources=natives(entry);if (sources!=null) { limit(sources.size(),false);for (int n=0;n<sources.size();n++) for (String member : sources.get(n).fields()) { String sourceAt=at+"["+n+"]."+member;if (NativeJigsawOverrides.OBJECT_FIELDS.contains(member)) { for (String detail : NativeJigsawOverrides.readOnlyPaths(sources.get(n))) paths.add(at+"["+n+"]."+detail); }else if (!NATIVE_FIELDS.contains(member)) paths.add(sourceAt);else try { if (member.equals("structure")) nativeKey(sources.get(n));else nativeWeight(sources.get(n)); } catch (IllegalArgumentException invalid) { paths.add(sourceAt); } } } }else if (List.of("structures","caveBiomes").contains(field)) { var refs=strings(entry,field);if (refs!=null) limit(refs.size(),false); }else if (BOOLEANS.contains(field)) bool(entry,field);else if (ENUMS.contains(field) || field.equals("placementId")) entry.stringToken(field);else number(entry,field); } catch (IllegalArgumentException invalid) { paths.add(at); } } } }catch (IllegalArgumentException invalid) { paths.add("structures"); }return List.copyOf(paths); }
}
